cat > stage2.sql << 'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;

CREATE TABLE raw AS
  SELECT row_number() OVER () - 1 AS rid, cod_imovel, municipio, cod_estado, geometry AS geom_wkt
  FROM read_csv('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);

SELECT count(*) FROM raw;

CREATE TABLE car_go AS SELECT * FROM read_parquet('/workspace/work/car_go.parquet');

-- classify rows
SELECT
  sum(CASE WHEN cod_imovel != '' THEN 1 ELSE 0 END) AS id_rows,
  sum(CASE WHEN cod_imovel = '' AND geom_wkt != '' THEN 1 ELSE 0 END) AS geom_rows,
  sum(CASE WHEN cod_imovel = '' AND geom_wkt = '' THEN 1 ELSE 0 END) AS neither
FROM raw;
EOF
