cd /workspace/work
cat > stage2.sql << 'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;

CREATE TABLE raw0 AS SELECT * FROM read_csv('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);
CREATE TABLE raw AS SELECT row_number() OVER () - 1 AS rid, cod_imovel, municipio, cod_estado, geometry AS geom_wkt FROM raw0;

CREATE TABLE car_go AS SELECT * FROM read_parquet('/workspace/work/car_go.parquet');

SELECT
  sum(CASE WHEN cod_imovel IS NOT NULL AND cod_imovel != '' THEN 1 ELSE 0 END) AS id_rows,
  sum(CASE WHEN (cod_imovel IS NULL OR cod_imovel = '') AND geom_wkt IS NOT NULL AND geom_wkt != '' THEN 1 ELSE 0 END) AS geom_rows,
  sum(CASE WHEN (cod_imovel IS NULL OR cod_imovel = '') AND (geom_wkt IS NULL OR geom_wkt = '') THEN 1 ELSE 0 END) AS neither
FROM raw;

SELECT rid, cod_imovel, geom_wkt FROM raw WHERE geom_wkt IS NOT NULL AND geom_wkt != '';
EOF
