SET geometry_always_xy = true;

-- Point resolution: find containing parcel(s) in car_go
CREATE OR REPLACE TABLE point_matches AS
SELECT g.rid, c.cod_imovel, c.municipio
FROM geom_resolved_input g
JOIN car_go c
  ON g.gtype = 'POINT' AND g.use_geom IS NOT NULL
  AND c.bbox.xmin <= ST_X(g.use_geom) AND c.bbox.xmax >= ST_X(g.use_geom)
  AND c.bbox.ymin <= ST_Y(g.use_geom) AND c.bbox.ymax >= ST_Y(g.use_geom)
  AND ST_Contains(c.geometry, g.use_geom);

SELECT * FROM point_matches;

